        const { data, error } = await supabase
          .from('leads')
          .insert([{
            name: lead.name,
            company: lead.company,
            status: lead.status,
            last_interaction: lead.lastInteraction,
            sentiment: lead.sentiment
          }])
          .select()
          .single();

        if (error) throw error;
        createdLead = {
