```sql
-- Create Leads Table
create table if not exists leads (
  id uuid default gen_random_uuid() primary key,
  created_at timestamp with time zone default timezone('utc'::text, now()) not null,
  name text not null,
  company text,
  status text check (status in ('New', 'Contacted', 'Qualified', 'Closed')) default 'New',
  last_interaction text,
  sentiment text check (sentiment in ('Positive', 'Neutral', 'Negative')) default 'Neutral'
);

-- Create Sessions Table for recording transcripts
create table if not exists sessions (
  id uuid default gen_random_uuid() primary key,
  lead_id uuid references leads(id) on delete cascade,
  created_at timestamp with time zone default timezone('utc'::text, now()) not null,
  transcript jsonb, -- Stores array of Message objects
  summary text
);

-- Create Agent Configs Table
create table if not exists agent_configs (
  id uuid default gen_random_uuid() primary key,
  created_at timestamp with time zone default timezone('utc'::text, now()) not null,
  updated_at timestamp with time zone default timezone('utc'::text, now()) not null,
  config jsonb not null
);

-- Enable RLS
alter table leads enable row level security;
alter table sessions enable row level security;
alter table agent_configs enable row level security;

-- Create Policies (Public Access for Demo Purposes)
create policy "Allow public read access to leads" on leads for select using (true);
create policy "Allow public insert access to leads" on leads for insert with check (true);
create policy "Allow public update access to leads" on leads for update using (true);
create policy "Allow public delete access to leads" on leads for delete using (true);

create policy "Allow public read access to sessions" on sessions for select using (true);
create policy "Allow public insert access to sessions" on sessions for insert with check (true);
create policy "Allow public update access to sessions" on sessions for update using (true);

create policy "Allow public read access to configs" on agent_configs for select using (true);
create policy "Allow public insert access to configs" on agent_configs for insert with check (true);
create policy "Allow public update access to configs" on agent_configs for update using (true);

To ensure that every session (Chat, Voice, or Hybrid) is recorded and stored in Supabase, I will implement the Session Recording Logic.

Here is the plan:
1.  **Database Layer (`services/db.ts`)**: Add methods to create a `Session` linked to a `Lead` and update its transcript in real-time.
2.  **Type Definitions (`types.ts`)**: Define the `Session` structure.
3.  **Voice Intelligence (`services/liveApi.ts`)**: Enable "Audio Transcription" in the Gemini Live configuration. This forces the model to return text versions of what it hears and what it speaks, allowing us to log voice conversations as text.
4.  **Application Logic (`App.tsx`)**:
    *   Create a new Session ID when a demo starts.
    *   Capture voice transcripts and inject them into the Chat UI.
    *   Automatically sync the entire message history to Supabase whenever it changes.

