    }

    try {
      const result = await chatSessionRef.current.sendMessage({ message: userText });
      const responseText = result.text;

      const modelMsg: Message = {
        id: (Date.now() + 1).toString(),
        role: 'model',
        text: responseText,
        timestamp: new Date()
      };
      setChatMessages(prev => [...prev, modelMsg]);
