type TabID = 'overview' | 'landing' | 'crm' | 'company' | 'products' | 'personas' | 'scripts' | 'objections' | 'faqs' | 'process' | 'pricing' | 'docs' | 'tone' | 'deploy';

// CSV Helper Functions (omitted for brevity, assume existing)
const exportToCSV = (data: any[], filename: string) => {
  if (!data || data.length === 0) {
    alert("No data to export");
    return;
  }
  const allKeys = Array.from(new Set(data.flatMap(item => Object.keys(item))));
  const csvContent = [
    allKeys.join(','),
    ...data.map(row => 
      allKeys.map(key => {
        const val = (row as any)[key];
        const stringVal = val === null || val === undefined ? '' : String(val);
        return `"${stringVal.replace(/"/g, '""')}"`; 
      }).join(',')
    )
  ].join('\n');
  const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
  const link = document.createElement("a");
  const url = URL.createObjectURL(blob);
  link.setAttribute("href", url);
  link.setAttribute("download", `${filename}_${new Date().toISOString().split('T')[0]}.csv`);
  link.style.visibility = 'hidden';
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
};

const importFromCSV = (file: File, callback: (data: any[]) => void) => {
  const reader = new FileReader();
  reader.onload = (e) => {
    const text = e.target?.result as string;
    if (!text) return;
    const lines = text.split(/\r\n|\n/).filter(line => line.trim() !== '');
    if (lines.length < 2) return;
    const headers = lines[0].split(',').map(h => h.trim());
    const parsedData = lines.slice(1).map((line, idx) => {
      const values = line.split(/,(?=(?:(?:[^"]*"){2})*[^"]*$)/);
      const obj: any = {};
      headers.forEach((header, i) => {
        let val = values[i] || '';
        val = val.trim();
        if (val.startsWith('"') && val.endsWith('"')) {
          val = val.substring(1, val.length - 1);
          val = val.replace(/""/g, '"');
        }
        obj[header] = val;
      });
      if (!obj.id) obj.id = `imported_${Date.now()}_${idx}`;
      return obj;
    });
    callback(parsedData);
  };
  reader.readAsText(file);
};

