## services/liveApi.ts

Added a mixing engine using `MediaStreamDestination` to record both the microphone and the AI's audio output into a single `webm` Blob, which is converted to Base64 for storage.

```typescript
import { GoogleGenAI, LiveServerMessage, Modality } from "@google/genai";
import { AgentConfig, AgentStatus } from "../types";

// Audio Helpers
function encode(bytes: Uint8Array) {
  let binary = '';
  const len = bytes.byteLength;
  for (let i = 0; i < len; i++) {
    binary += String.fromCharCode(bytes[i]);
  }
  return btoa(binary);
}

function decode(base64: string) {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number,
  numChannels: number,
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

function createBlob(data: Float32Array): { data: string; mimeType: string } {
  const l = data.length;
  const int16 = new Int16Array(l);
  for (let i = 0; i < l; i++) {
    int16[i] = data[i] * 32768;
  }
  return {
    data: encode(new Uint8Array(int16.buffer)),
    mimeType: 'audio/pcm;rate=16000',
  };
}

export class LiveClient {
  private ai: GoogleGenAI;
  private config: AgentConfig;
  private inputAudioContext: AudioContext | null = null;
  private outputAudioContext: AudioContext | null = null;
  private inputNode: ScriptProcessorNode | null = null;
  private outputNode: GainNode | null = null;
  private outputAnalyser: AnalyserNode | null = null;
  private sources: Set<AudioBufferSourceNode> = new Set();
  private nextStartTime: number = 0;
  private stream: MediaStream | null = null;
  private sessionPromise: Promise<any> | null = null;
  private outputVolumeInterval: number | null = null;
  private currentStatus: AgentStatus = 'idle';
  private lastUserInteraction: number = 0;
  private hasSpokenOnce: boolean = false;

  // Recording
  private mediaRecorder: MediaRecorder | null = null;
  private recordedChunks: Blob[] = [];
  private recordingDestination: MediaStreamAudioDestinationNode | null = null;

  // Accumulate partial transcripts
  private currentInputTranscription: string = '';
  private currentOutputTranscription: string = '';

  public onVolumeUpdate: ((vol: number) => void) | null = null;
  public onStatusChange: ((status: AgentStatus) => void) | null = null;
  public onTranscript: ((text: string, role: 'user' | 'model') => void) | null = null;
  public onAudioRecordingComplete: ((base64Audio: string) => void) | null = null;

  constructor(config: AgentConfig) {
    this.ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    this.config = config;
  }

  private setStatus(status: AgentStatus) {
    if (this.currentStatus === 'error' && status !== 'idle' && status !== 'connecting') return;
    this.currentStatus = status;
    if (this.onStatusChange) this.onStatusChange(status);
  }

  async connect() {
    this.setStatus('connecting');

    try {
      // 1. Setup Audio Contexts
      this.inputAudioContext = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
      this.outputAudioContext = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });

      // 2. Setup Output Node (To Speakers)
      this.outputNode = this.outputAudioContext.createGain();
      this.outputAnalyser = this.outputAudioContext.createAnalyser();
      this.outputAnalyser.fftSize = 256;
      this.outputNode.connect(this.outputAnalyser);
      this.outputAnalyser.connect(this.outputAudioContext.destination);

      // 3. Setup Recording Destination (Mixer) in Input Context to simplify
      // Note: Cross-context recording is complex. Simpler approach:
      // We will rely on browser's MediaRecorder on the input stream and *try* to mix, 
      // but strictly speaking, capturing AI audio requiring piping output context to a destination.

      // Better Recording Strategy: Record primarily the user for now to ensure stability, 
      // OR use a single context if possible. 
      // Let's use a destination node on the OUTPUT context to capture AI, and stream User audio to it.
      this.recordingDestination = this.outputAudioContext.createMediaStreamDestination();
      this.outputNode.connect(this.recordingDestination); // AI audio goes to recorder

      // 4. Get User Media
      this.stream = await navigator.mediaDevices.getUserMedia({ audio: true });

      // Add Mic to Recording Mixer
      const micSourceForRecord = this.outputAudioContext.createMediaStreamSource(this.stream);
      micSourceForRecord.connect(this.recordingDestination);

      // Start Recorder
      this.mediaRecorder = new MediaRecorder(this.recordingDestination.stream);
      this.recordedChunks = [];
      this.mediaRecorder.ondataavailable = (event) => {
        if (event.data.size > 0) {
          this.recordedChunks.push(event.data);
        }
      };
      this.mediaRecorder.start();

      this.sessionPromise = this.ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-09-2025',
        callbacks: {
          onopen: () => {
            this.setStatus('listening');
            this.startAudioInput(); // This uses inputAudioContext for 16khz processing
            this.startOutputVolumeMonitoring();
          },
          onmessage: async (message: LiveServerMessage) => {
            this.handleMessage(message);
          },
          onerror: (e) => {
            console.error("Live API Error:", e);
            this.setStatus('error');
          },
          onclose: () => {
            console.log("Live API Closed");
            this.setStatus('idle');
          }
        },
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: {
            voiceConfig: { prebuiltVoiceConfig: { voiceName: this.config.voiceName } },
          },
          systemInstruction: { parts: [{ text: this.config.systemInstruction }] },
          inputAudioTranscription: {},
          outputAudioTranscription: {}
        }
      });
    } catch (e) {
      console.error("Connection failed", e);
      this.setStatus('error');
    }
  }

  private startOutputVolumeMonitoring() {
    if (this.outputVolumeInterval) clearInterval(this.outputVolumeInterval);
    const dataArray = new Uint8Array(this.outputAnalyser!.frequencyBinCount);
    this.outputVolumeInterval = window.setInterval(() => {
      if (this.currentStatus === 'speaking' && this.outputAnalyser && this.onVolumeUpdate) {
        this.outputAnalyser.getByteFrequencyData(dataArray);
        let sum = 0;
        for (let i = 0; i < dataArray.length; i++) sum += dataArray[i];
        const average = sum / dataArray.length;
        this.onVolumeUpdate(average / 128.0);
      }
    }, 50);
  }

  private startAudioInput() {
    if (!this.inputAudioContext || !this.stream || !this.sessionPromise) return;

    const source = this.inputAudioContext.createMediaStreamSource(this.stream);
    this.inputNode = this.inputAudioContext.createScriptProcessor(4096, 1, 1);

    this.inputNode.onaudioprocess = (e) => {
      const inputData = e.inputBuffer.getChannelData(0);
      let sum = 0;
      for(let i=0; i<inputData.length; i++) sum += inputData[i] * inputData[i];
      const rms = Math.sqrt(sum / inputData.length);

      if (this.currentStatus !== 'speaking' && this.onVolumeUpdate) {
        this.onVolumeUpdate(rms * 5);
      }

      if (rms > 0.02) {
        this.lastUserInteraction = Date.now();
        this.hasSpokenOnce = true;
        if (this.currentStatus !== 'listening' && this.currentStatus !== 'speaking') {
           this.setStatus('listening');
        }
      } else if (this.currentStatus === 'listening' && this.hasSpokenOnce) {
        const timeSinceSpeech = Date.now() - this.lastUserInteraction;
        if (timeSinceSpeech > 800 && timeSinceSpeech < 3000) {
           this.setStatus('processing');
        }
      }

      const pcmBlob = createBlob(inputData);
      this.sessionPromise?.then((session) => {
        session.sendRealtimeInput({ media: pcmBlob });
      });
    };

    source.connect(this.inputNode);
    this.inputNode.connect(this.inputAudioContext.destination);
  }

  private async handleMessage(message: LiveServerMessage) {
    if (message.serverContent?.outputTranscription?.text) {
      this.currentOutputTranscription += message.serverContent.outputTranscription.text;
    }
    if (message.serverContent?.inputTranscription?.text) {
      this.currentInputTranscription += message.serverContent.inputTranscription.text;
    }

    if (message.serverContent?.turnComplete) {
      if (this.currentInputTranscription.trim() && this.onTranscript) {
        this.onTranscript(this.currentInputTranscription, 'user');
        this.currentInputTranscription = '';
      }
      if (this.currentOutputTranscription.trim() && this.onTranscript) {
        this.onTranscript(this.currentOutputTranscription, 'model');
        this.currentOutputTranscription = '';
      }
    }

    const base64Audio = message.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
    if (base64Audio && this.outputAudioContext && this.outputNode) {
      if (this.currentStatus !== 'speaking') {
        this.setStatus('speaking');
      }
      this.nextStartTime = Math.max(this.nextStartTime, this.outputAudioContext.currentTime);
      const audioBuffer = await decodeAudioData(decode(base64Audio), this.outputAudioContext, 24000, 1);
      const source = this.outputAudioContext.createBufferSource();
      source.buffer = audioBuffer;
      source.connect(this.outputNode);
      source.addEventListener('ended', () => {
        this.sources.delete(source);
        if (this.sources.size === 0) {
          this.setStatus('listening');
          this.lastUserInteraction = 0;
          this.hasSpokenOnce = false;
        }
      });
      source.start(this.nextStartTime);
      this.nextStartTime += audioBuffer.duration;
      this.sources.add(source);
    }

    const interrupted = message.serverContent?.interrupted;
    if (interrupted) {
      this.sources.forEach(s => s.stop());
      this.sources.clear();
      this.nextStartTime = 0;
      this.setStatus('listening');
      this.lastUserInteraction = 0;
      this.hasSpokenOnce = false;
      this.currentOutputTranscription = '';
    }
  }

  async disconnect() {
    if (this.mediaRecorder && this.mediaRecorder.state !== 'inactive') {
      this.mediaRecorder.stop();
      // Wait for stop event to fire and collect blobs
      await new Promise<void>((resolve) => {
        this.mediaRecorder!.onstop = async () => {
          const blob = new Blob(this.recordedChunks, { type: 'audio/webm' });
          const reader = new FileReader();
          reader.readAsDataURL(blob);
          reader.onloadend = () => {
            const base64data = reader.result as string;
            if (this.onAudioRecordingComplete) {
              this.onAudioRecordingComplete(base64data);
            }
            resolve();
          };
        };
      });
    }

    if (this.outputVolumeInterval) {
      clearInterval(this.outputVolumeInterval);
      this.outputVolumeInterval = null;
    }

    if (this.stream) {
      this.stream.getTracks().forEach(track => track.stop());
      this.stream = null;
    }

    if (this.inputNode) {
      this.inputNode.disconnect();
      this.inputNode = null;
    }

    if (this.inputAudioContext) {
      if (this.inputAudioContext.state !== 'closed') {
        try {
          await this.inputAudioContext.close();
        } catch (e) {
          console.error("Error closing inputAudioContext", e);
        }
      }
      this.inputAudioContext = null;
    }

    if (this.outputAudioContext) {
      if (this.outputAudioContext.state !== 'closed') {
        try {
          await this.outputAudioContext.close();
        } catch (e) {
           console.error("Error closing outputAudioContext", e);
        }
      }
      this.outputAudioContext = null;
    }

    this.sources.forEach(s => s.stop());
    this.sources.clear();
    this.setStatus('idle');
  }
}
