```typescript
import { supabase, isSupabaseConfigured } from './supabaseClient';
import { AgentConfig, Lead, Session, Message, SessionAnalysis } from '../types';

// Storage Keys for Fallback Mode
const LOCAL_CONFIG_KEY = 'nova_agent_config';
const LOCAL_LEADS_KEY = 'nova_agent_leads';
const LOCAL_SESSIONS_KEY = 'nova_agent_sessions';

// Helper to safely get local storage data
const getLocal = <T>(key: string, defaultVal: T): T => {
  try {
    const item = localStorage.getItem(key);
    return item ? JSON.parse(item) : defaultVal;
  } catch (e) {
    console.warn(`Failed to parse local storage for ${key}`, e);
    return defaultVal;
  }
};

const setLocal = (key: string, value: any) => {
  try {
    localStorage.setItem(key, JSON.stringify(value));
  } catch (e) {
    console.warn(`Failed to save to local storage for ${key}`, e);
  }
};

export const db = {
  // --- Agent Configuration ---

  async getAgentConfig(): Promise<AgentConfig | null> {
    if (isSupabaseConfigured) {
      try {
        const { data, error } = await supabase
          .from('agent_configs')
          .select('config')
          .limit(1)
          .maybeSingle();

        if (error) throw error;
        if (data?.config) return data.config as AgentConfig;
        return null; 
      } catch (e: any) {
        console.warn('Supabase config fetch failed (using local fallback):', e.message || e);
      }
    }
    return getLocal<AgentConfig | null>(LOCAL_CONFIG_KEY, null);
  },

  async saveAgentConfig(config: AgentConfig): Promise<boolean> {
    if (isSupabaseConfigured) {
      try {
        const { data: existing } = await supabase.from('agent_configs').select('id').limit(1);
        let result;
        if (existing && existing.length > 0) {
          result = await supabase
            .from('agent_configs')
            .update({ config, updated_at: new Date() })
            .eq('id', existing[0].id);
        } else {
          result = await supabase
            .from('agent_configs')
            .insert([{ config }]);
        }
        if (result.error) throw result.error;
      } catch (e: any) {
        console.warn('Supabase save config failed:', e.message || e);
      }
    }
    setLocal(LOCAL_CONFIG_KEY, config);
    return true;
  },

  // --- Leads ---

  async getLeads(): Promise<Lead[]> {
    if (isSupabaseConfigured) {
      try {
        const { data, error } = await supabase
          .from('leads')
          .select('*')
          .order('created_at', { ascending: false });

        if (error) throw error;
        return data.map((row: any) => ({
          id: row.id,
          name: row.name,
          company: row.company,
          status: row.status,
          lastInteraction: row.last_interaction,
          sentiment: row.sentiment,
          email: row.email,
          phone: row.phone,
          leadScore: row.lead_score || 50,
          dealValue: row.deal_value || 0,
          nextStep: row.next_step
        })) as Lead[];
      } catch (e: any) {
        console.warn('Supabase leads fetch failed (using local fallback):', e.message || e);
      }
    }
    return getLocal<Lead[]>(LOCAL_LEADS_KEY, []);
  },

  async createLead(lead: Omit<Lead, 'id'>): Promise<Lead | null> {
    // Generate realistic defaults for the new fields
    const enhancedLead = {
        ...lead,
        email: `contact.${Math.floor(Math.random()*1000)}@${lead.company.toLowerCase().replace(/\s/g, '')}.com`,
        phone: `+20 1${Math.floor(Math.random()*10)} ${Math.floor(Math.random()*1000)} ${Math.floor(Math.random()*10000)}`,
        leadScore: Math.floor(Math.random() * 60) + 20, // Start between 20 and 80
        dealValue: Math.floor(Math.random() * 5000) + 500, // Random deal value
        nextStep: 'Needs Analysis'
    };

    let createdLead: Lead | null = null;
    if (isSupabaseConfigured) {
      try {
        const { data, error } = await supabase
          .from('leads')
          .insert([{
            name: enhancedLead.name,
            company: enhancedLead.company,
            status: enhancedLead.status,
            last_interaction: enhancedLead.lastInteraction,
            sentiment: enhancedLead.sentiment,
            email: enhancedLead.email,
            phone: enhancedLead.phone,
            lead_score: enhancedLead.leadScore,
            deal_value: enhancedLead.dealValue,
            next_step: enhancedLead.nextStep
          }])
          .select()
          .single();

        if (error) throw error;
        createdLead = {
          id: data.id,
          name: data.name,
          company: data.company,
          status: data.status,
          lastInteraction: data.last_interaction,
          sentiment: data.sentiment,
          email: data.email,
          phone: data.phone,
          leadScore: data.lead_score,
          dealValue: data.deal_value,
          nextStep: data.next_step
        };
      } catch (e: any) {
        console.warn('Supabase create lead failed:', e.message || e);
      }
    }

    if (!createdLead) {
      createdLead = { ...enhancedLead, id: Date.now().toString() };
    }
    const currentLocal = getLocal<Lead[]>(LOCAL_LEADS_KEY, []);
    setLocal(LOCAL_LEADS_KEY, [createdLead, ...currentLocal]);
    return createdLead;
  },

  async updateLead(id: string, updates: Partial<Lead>) {
    if (isSupabaseConfigured) {
      try {
        const dbUpdates: any = {};
        if (updates.name) dbUpdates.name = updates.name;
        if (updates.company) dbUpdates.company = updates.company;
        if (updates.status) dbUpdates.status = updates.status;
        if (updates.lastInteraction) dbUpdates.last_interaction = updates.lastInteraction;
        if (updates.sentiment) dbUpdates.sentiment = updates.sentiment;
        // New fields
        if (updates.email) dbUpdates.email = updates.email;
        if (updates.phone) dbUpdates.phone = updates.phone;
        if (updates.leadScore !== undefined) dbUpdates.lead_score = updates.leadScore;
        if (updates.dealValue !== undefined) dbUpdates.deal_value = updates.dealValue;
        if (updates.nextStep) dbUpdates.next_step = updates.nextStep;

        const { error } = await supabase.from('leads').update(dbUpdates).eq('id', id);
        if (error) throw error;
      } catch (e: any) {
        console.warn('Supabase update lead failed:', e.message || e);
      }
    }
    const leads = getLocal<Lead[]>(LOCAL_LEADS_KEY, []);
    const updatedLeads = leads.map(l => l.id === id ? { ...l, ...updates } : l);
    setLocal(LOCAL_LEADS_KEY, updatedLeads);
  },

  // ... (rest of the file like deleteLead, sessions logic remains unchanged from previous turn)
  async deleteLead(id: string) {
    if (isSupabaseConfigured) {
      try {
        const { error } = await supabase.from('leads').delete().eq('id', id);
        if (error) throw error;
      } catch (e: any) {
        console.warn('Supabase delete lead failed:', e.message || e);
      }
    }
    const leads = getLocal<Lead[]>(LOCAL_LEADS_KEY, []);
    const filtered = leads.filter(l => l.id !== id);
    setLocal(LOCAL_LEADS_KEY, filtered);
  },

  async getSessions(leadId: string): Promise<Session[]> {
    if (isSupabaseConfigured) {
      try {
        const { data, error } = await supabase
          .from('sessions')
          .select('*')
          .eq('lead_id', leadId)
          .order('created_at', { ascending: false });

        if (error) throw error;

        return data.map((row: any) => ({
          id: row.id,
          leadId: row.lead_id,
          createdAt: row.created_at,
          transcript: row.transcript || [],
          audioData: row.audio_data,
          analysis: row.analysis
        })) as Session[];
      } catch (e: any) {
        console.warn('Supabase get sessions failed:', e);
      }
    }
    const allSessions = getLocal<Session[]>(LOCAL_SESSIONS_KEY, []);
    return allSessions.filter(s => s.leadId === leadId).sort((a, b) => 
      new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime()
    );
  },

  async createSession(leadId: string): Promise<Session | null> {
    let createdSession: Session | null = null;
    if (isSupabaseConfigured) {
      try {
        const { data, error } = await supabase
          .from('sessions')
          .insert([{ lead_id: leadId, transcript: [] }])
          .select()
          .single();
        if (error) throw error;
        createdSession = {
          id: data.id,
          leadId: data.lead_id,
          createdAt: data.created_at,
          transcript: data.transcript || []
        };
      } catch (e: any) {
        console.warn('Supabase create session failed:', e);
      }
    }
    if (!createdSession) {
      createdSession = {
        id: Date.now().toString(),
        leadId,
        createdAt: new Date().toISOString(),
        transcript: []
      };
    }
    const sessions = getLocal<Session[]>(LOCAL_SESSIONS_KEY, []);
    setLocal(LOCAL_SESSIONS_KEY, [createdSession, ...sessions]);
    return createdSession;
  },

  async updateSessionTranscript(sessionId: string, transcript: Message[]) {
    const serializableTranscript = transcript.map(m => ({
      ...m,
      timestamp: m.timestamp instanceof Date ? m.timestamp.toISOString() : m.timestamp
    }));
    if (isSupabaseConfigured) {
      try {
        const { error } = await supabase
          .from('sessions')
          .update({ transcript: serializableTranscript })
          .eq('id', sessionId);
        if (error) throw error;
      } catch (e: any) {}
    }
    const sessions = getLocal<Session[]>(LOCAL_SESSIONS_KEY, []);
    const updatedSessions = sessions.map(s => s.id === sessionId ? { ...s, transcript } : s);
    setLocal(LOCAL_SESSIONS_KEY, updatedSessions);
  },

  async saveSessionRecording(sessionId: string, audioBase64: string) {
    if (isSupabaseConfigured) {
      try {
        const { error } = await supabase
          .from('sessions')
          .update({ audio_data: audioBase64 })
          .eq('id', sessionId);
        if (error) throw error;
      } catch (e) {
        console.warn("Failed to upload recording to DB", e);
      }
    }
    const sessions = getLocal<Session[]>(LOCAL_SESSIONS_KEY, []);
    const updatedSessions = sessions.map(s => s.id === sessionId ? { ...s, audioData: audioBase64 } : s);
    setLocal(LOCAL_SESSIONS_KEY, updatedSessions);
  },

  async saveSessionAnalysis(sessionId: string, analysis: SessionAnalysis) {
    if (isSupabaseConfigured) {
      try {
        const { error } = await supabase
          .from('sessions')
          .update({ analysis: analysis })
          .eq('id', sessionId);
        if (error) throw error;
      } catch (e) {
        console.warn("Failed to upload analysis to DB", e);
      }
    }
    const sessions = getLocal<Session[]>(LOCAL_SESSIONS_KEY, []);
    const updatedSessions = sessions.map(s => s.id === sessionId ? { ...s, analysis } : s);
    setLocal(LOCAL_SESSIONS_KEY, updatedSessions);
  }
};
