import React, { useState, useMemo } from 'react';
import { Lead } from '../types';

interface CRMTableProps {
  leads: Lead[];
  onUpdateLead: (id: string, updates: Partial<Lead>) => void;
  onDeleteLead: (id: string) => void;
  onViewHistory: (lead: Lead) => void;
}

type SortConfig = {
  key: keyof Lead | 'date';
  direction: 'asc' | 'desc';
};

const CRMTable: React.FC<CRMTableProps> = ({ leads, onUpdateLead, onDeleteLead, onViewHistory }) => {
  const [sortConfig, setSortConfig] = useState<SortConfig>({ key: 'lastInteraction', direction: 'desc' });
  const [filters, setFilters] = useState<Record<string, string>>({});

  const handleSort = (key: keyof Lead | 'date') => {
    let direction: 'asc' | 'desc' = 'asc';
    if (sortConfig.key === key && sortConfig.direction === 'asc') {
      direction = 'desc';
    }
    setSortConfig({ key, direction });
  };

  const handleFilterChange = (key: string, value: string) => {
    setFilters(prev => ({ ...prev, [key]: value }));
  };

  const filteredLeads = useMemo(() => {
    return leads.filter(lead => {
      for (const key in filters) {
        if (!filters[key]) continue;
        const val = (lead as any)[key]?.toString().toLowerCase() || '';
        if (!val.includes(filters[key].toLowerCase())) return false;
      }
      return true;
    });
  }, [leads, filters]);

  const sortedLeads = useMemo(() => {
    const sorted = [...filteredLeads];
    sorted.sort((a, b) => {
      const aVal = (a as any)[sortConfig.key];
      const bVal = (b as any)[sortConfig.key];

      // Handle numeric sorting
      if (sortConfig.key === 'leadScore' || sortConfig.key === 'dealValue') {
         return sortConfig.direction === 'asc' ? aVal - bVal : bVal - aVal;
      }

      // Handle string sorting
      if (aVal < bVal) return sortConfig.direction === 'asc' ? -1 : 1;
      if (aVal > bVal) return sortConfig.direction === 'asc' ? 1 : -1;
      return 0;
    });
    return sorted;
  }, [filteredLeads, sortConfig]);

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'New': return 'bg-blue-500/10 text-blue-400 border-blue-500/30';
      case 'Contacted': return 'bg-yellow-500/10 text-yellow-400 border-yellow-500/30';
