  const getScoreColor = (score: number) => {
    if (score >= 80) return 'text-green-400';
    if (score >= 50) return 'text-yellow-400';
    return 'text-red-400';
  };

  const SortIcon = ({ colKey }: { colKey: string }) => (
    <span className="ml-1 text-[10px] opacity-50">
      {sortConfig.key === colKey ? (sortConfig.direction === 'asc' ? '▲' : '▼') : '↕'}
    </span>
  );

  return (
    <div className="w-full overflow-hidden rounded-xl border border-white/10 glass-panel shadow-2xl">
      <div className="overflow-x-auto min-h-[500px]">
        <table className="w-full text-left text-sm text-gray-400">
          <thead className="bg-white/5 text-gray-200 font-arabic border-b border-white/10">
            <tr>
              {/* --- Name Column --- */}
              <th className="px-4 py-3 min-w-[180px]">
                <div className="flex flex-col gap-2">
                  <button onClick={() => handleSort('name')} className="flex items-center font-semibold hover:text-white uppercase tracking-wider text-xs">
                    Lead Name <SortIcon colKey="name" />
                  </button>
                  <input 
                    type="text" 
                    placeholder="Search..." 
                    className="w-full bg-black/30 border border-white/10 rounded px-2 py-1 text-xs focus:border-neon-blue focus:outline-none"
                    onChange={(e) => handleFilterChange('name', e.target.value)}
                  />
                </div>
              </th>

              {/* --- Company Column --- */}
              <th className="px-4 py-3 min-w-[150px]">
                <div className="flex flex-col gap-2">
                  <button onClick={() => handleSort('company')} className="flex items-center font-semibold hover:text-white uppercase tracking-wider text-xs">
                    Company <SortIcon colKey="company" />
                  </button>
                  <input 
                    type="text" 
                    placeholder="Filter..." 
                    className="w-full bg-black/30 border border-white/10 rounded px-2 py-1 text-xs focus:border-neon-blue focus:outline-none"
                    onChange={(e) => handleFilterChange('company', e.target.value)}
